ALTER TABLE public.academy_courses ADD COLUMN IF NOT EXISTS content_ready boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS publication_approved boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS production_gaps text[] NOT NULL DEFAULT '{}'; CREATE POLICY "courses: existing learners read archived" ON public.academy_courses FOR SELECT TO authenticated USING (public.is_enrolled_in_course(auth.uid(),id)); CREATE OR REPLACE FUNCTION public.validate_flagship_course() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.slug IN ('ai-for-agribusinesses','finance-ready','business-growth-accelerator','ai-business-transformation','climate-smart-agribusiness','development-project-design') THEN NEW.regular_price := 25000; NEW.discount_price := NULL; IF NEW.status='enrolment_open' AND (NOT NEW.content_ready OR NOT NEW.publication_approved OR cardinality(NEW.production_gaps)>0 OR NOT EXISTS(SELECT 1 FROM public.academy_lessons WHERE course_id=NEW.id AND nullif(description,'') IS NOT NULL)) THEN RAISE EXCEPTION 'Complete content and publication approval before opening enrolment'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER validate_flagship_course BEFORE INSERT OR UPDATE ON public.academy_courses FOR EACH ROW EXECUTE FUNCTION public.validate_flagship_course();